        b[1][6] = b[2][6] = b[3][6] = 'w'
        b[1][7] = b[2][7] = b[3][7] = 'w'
        b[1][9] = b[2][9] = b[3][9] = 'w'
        b[1][10] = b[2][10] = b[3][10] = 'w'
        b[1][11] = b[2][11] = b[3][11] = 'w'

