    try:
        inner = action[action.index("(") + 1:action.index(")")]
        parts = inner.split(",")
        row = int(parts[0].split("=")[1].strip())
        col = int(parts[1].split("=")[1].strip())
    except Exception:
        return board_lines

    if not (0 <= row < 64 and 0 <= col < 64):
        return board_lines

    b = [list(line) for line in board_lines]

    # --- Determine tile containing (row, col) ---
    def tile_of(r, c):
        if not (2 <= r <= 23 and 4 <= c <= 25):
            return None
        tr = (r - 2) // 8
        tc = (c - 4) // 8
        if 0 <= tr <= 2 and 0 <= tc <= 2:
            return (tr, tc)
        return None

    # --- Initial tile colors (the reset pattern) ---
    INIT = [
        ['b', 'R', 'b'],
        ['R', 'b', 'R'],
        ['b', 'R', 'b'],
    ]

    def tile_top_left(ti):
        tr, tc = ti
        return 2 + tr * 8, 4 + tc * 8

    def set_tile(ti, color):
        r0, c0 = tile_top_left(ti)
        for dr in range(6):
            for dc in range(6):
                b[r0 + dr][c0 + dc] = color

    # --- Read current tile colors ---
    tiles = []
    for tr in range(3):
        row_colors = []
        for tc in range(3):
            r0, c0 = tile_top_left((tr, tc))
            row_colors.append(b[r0][c0])
        tiles.append(row_colors)

    # --- Count yellow pixels in progress bar ---
    yellow_count = sum(1 for c in range(64) if b[63][c] == 'Y')

    # --- Render score display (columns 60-63, rows 0-6) ---
    def render_score(ny):
        digits = str(ny).rjust(4, '0')
        digit_map = {
            '0': ['b', 'O', 'O', 'O'],
            '1': ['b', 'O', 'O', 'Y'],
            '2': ['b', 'O', 'Y', 'Y'],
            '3': ['b', 'Y', 'Y', 'Y'],
            '4': ['O', 'Y', 'Y', 'Y'],
            '5': ['O', 'O', 'Y', 'Y'],
            '6': ['O', 'O', 'O', 'Y'],
            '7': ['O', 'O', 'O', 'O'],
            '8': ['Y', 'Y', 'Y', 'Y'],
            '9': ['Y', 'Y', 'Y', 'Y'],
        }
        for rr in range(7):
            for cc in range(4):
                b[rr][60 + cc] = digit_map[digits[cc]][rr]

    # --- Case 1: Click on bottom progress bar -> new game ---
    if row == 63:
        # Reset all tiles to initial colors
        for tr in range(3):
            for tc in range(3):
                set_tile((tr, tc), INIT[tr][tc])
        # Reset progress bar to all orange
        for c in range(64):
            b[63][c] = 'O'
        # Render score for 0 yellow
        render_score(0)
        return [''.join(line) for line in b]

    # --- Case 2: Click on a tile -> toggle selection ---
    ti = tile_of(row, col)
    if ti is not None:
        tr, tc = ti
        if tiles[tr][tc] == 'b':
            set_tile(ti, 'O')
        elif tiles[tr][tc] == 'O':
            set_tile(ti, 'b')
        # Update progress bar: rightmost 2 orange -> yellow
        for c in range(63, -1, -1):
            if b[63][c] == 'O':
                b[63][c] = 'Y'
                if c > 0 and b[63][c - 1] == 'O':
                    b[63][c - 1] = 'Y'
                break
        render_score(yellow_count + 2)
        return [''.join(line) for line in b]

    # --- Case 3: Click on a separator -> swap adjacent tiles ---
    # Horizontal separator: between tile rows tr and tr+1, at rows 8+tr*8, 9+tr*8
    # Vertical separator: between tile cols tc and tc+1, at cols 10+tc*8, 11+tc*8
    swapped = False
    for tr in range(2):
        if row in (8 + tr * 8, 9 + tr * 8):
            for tc in range(3):
                if 4 + tc * 8 <= col <= 9 + tc * 8:
                    # Swap tiles (tr, tc) and (tr+1, tc)
                    c1, c2 = tiles[tr][tc], tiles[tr + 1][tc]
                    set_tile((tr, tc), c2)
                    set_tile((tr + 1, tc), c1)
                    swapped = True
                    break
            if swapped:
                break

    if not swapped:
        for tc in range(2):
            if col in (10 + tc * 8, 11 + tc * 8):
                for tr in range(3):
                    if 2 + tr * 8 <= row <= 7 + tr * 8:
                        # Swap tiles (tr, tc) and (tr, tc+1)
                        c1, c2 = tiles[tr][tc], tiles[tr][tc + 1]
                        set_tile((tr, tc), c2)
                        set_tile((tr, tc + 1), c1)
                        swapped = True
                        break
                if swapped:
                    break

    if swapped:
        # Update progress bar
        for c in range(63, -1, -1):
            if b[63][c] == 'O':
                b[63][c] = 'Y'
                if c > 0 and b[63][c - 1] == 'O':
                    b[63][c - 1] = 'Y'
                break
        render_score(yellow_count + 2)
    # else: no change (clicked empty black space)

    return [''.join(line) for line in b]
